import{_ as t,o as e,c as a,a2 as p}from"./chunks/framework.A5mep7Fe.js";const q=JSON.parse('{"title":"💻 开发岗真题（30+）","description":"","frontmatter":{},"headers":[],"relativePath":"面试真题集/开发岗真题.md","filePath":"面试真题集/开发岗真题.md","lastUpdated":1786806808000}'),r={name:"面试真题集/开发岗真题.md"};function n(l,o,c,s,u,b){return e(),a("div",null,[...o[0]||(o[0]=[p('<h1 id="💻-开发岗真题-30" tabindex="-1">💻 开发岗真题（30+） <a class="header-anchor" href="#💻-开发岗真题-30" aria-label="Permalink to &quot;💻 开发岗真题（30+）&quot;">​</a></h1><blockquote><p>覆盖：Python/Java/Go/C++、前端/后端/测试/运维、AI 应用开发、系统设计。兼顾通用工程与 AI 场景。</p></blockquote><hr><h2 id="一、python" tabindex="-1">一、Python <a class="header-anchor" href="#一、python" aria-label="Permalink to &quot;一、Python&quot;">​</a></h2><p><strong>1. GIL 是什么、如何真正并行？</strong></p><blockquote><p>同进程同刻仅一线程执行字节码；用 multiprocessing 或多进程/C 扩展；IO 用 asyncio。</p></blockquote><p><strong>2. asyncio 适合什么？</strong></p><blockquote><p>高并发 IO（批量 LLM 请求、流式输出），CPU 密集仍受 GIL 限。</p></blockquote><p><strong>3. 默认可变参数陷阱？</strong></p><blockquote><p>默认参数在函数定义时绑定，可变对象（list）会被多次调用共享 → 用 None 默认再初始化。</p></blockquote><p><strong>4. 深拷贝浅拷贝区别？</strong></p><blockquote><p>浅拷贝共享嵌套对象引用；深拷贝递归复制全部，互不干扰。</p></blockquote><h2 id="二、java" tabindex="-1">二、Java <a class="header-anchor" href="#二、java" aria-label="Permalink to &quot;二、Java&quot;">​</a></h2><p><strong>5. HashMap 线程安全吗？</strong></p><blockquote><p>不安全；并发用 ConcurrentHashMap（细粒度锁/CAS）。</p></blockquote><p><strong>6. JVM GC 常见算法？</strong></p><blockquote><p>G1（可预测停顿）、ZGC（超低停顿，大堆友好）。调优看 OOM/停顿。</p></blockquote><p><strong>7. synchronized vs volatile？</strong></p><blockquote><p>volatile 保证可见性不保证原子；synchronized 保证原子+可见+有序（互斥）。</p></blockquote><p><strong>8. Java 怎么流式输出 LLM？</strong></p><blockquote><p>SSE/WebSocket 实时推前端；后端响应式 client 消费上游流式并转发。</p></blockquote><h2 id="三、go" tabindex="-1">三、Go <a class="header-anchor" href="#三、go" aria-label="Permalink to &quot;三、Go&quot;">​</a></h2><p><strong>9. goroutine vs 线程？</strong></p><blockquote><p>goroutine 用户态调度、栈仅几 KB，单机可百万级；OS 线程重（MB 级）。</p></blockquote><p><strong>10. Channel 关闭注意？</strong></p><blockquote><p>向关闭 channel 发送 panic；多生产者谨慎关闭；for-range 自动退出。</p></blockquote><p><strong>11. Go 适合写 LLM 推理服务吗？</strong></p><blockquote><p>适合网关/编排/代理层（高并发易部署）；模型计算仍在 Python/C++ 引擎。</p></blockquote><h2 id="四、c-c" tabindex="-1">四、C/C++ <a class="header-anchor" href="#四、c-c" aria-label="Permalink to &quot;四、C/C++&quot;">​</a></h2><p><strong>12. shared_ptr 坑？</strong></p><blockquote><p>循环引用泄漏（weak_ptr 打破）；引用计数原子开销；大对象用移动。</p></blockquote><p><strong>13. RAII 是什么？</strong></p><blockquote><p>资源获取即初始化，用对象生命周期管理资源，异常安全，C++ 核心惯用法。</p></blockquote><p><strong>14. 为什么推理引擎多用 C++？</strong></p><blockquote><p>对硬件极致优化、零成本抽象，适合低延迟高吞吐推理与算子。</p></blockquote><h2 id="五、前端" tabindex="-1">五、前端 <a class="header-anchor" href="#五、前端" aria-label="Permalink to &quot;五、前端&quot;">​</a></h2><p><strong>15. SSE vs WebSocket（AI 流式）？</strong></p><blockquote><p>SSE 单向服务端→客户端、简单、自动重连，适合 LLM 流式；WebSocket 双向适合实时交互。</p></blockquote><p><strong>16. 长对话前端怎么不卡？</strong></p><blockquote><p>虚拟列表、分片加载、消息分组、避免全量重渲染。</p></blockquote><p><strong>17. AI Chat UI 关键能力？</strong></p><blockquote><p>流式渲染、Markdown/代码高亮、思维链展示、工具调用可视化、错误降级。</p></blockquote><h2 id="六、后端-架构" tabindex="-1">六、后端 / 架构 <a class="header-anchor" href="#六、后端-架构" aria-label="Permalink to &quot;六、后端 / 架构&quot;">​</a></h2><p><strong>18. AI 后端和普通后端最大区别？</strong></p><blockquote><p>多「不确定性+高延迟+高成本」：需流式、缓存、降级、成本计量、并发控制。</p></blockquote><p><strong>19. 怎么做 LLM 调用缓存降本？</strong></p><blockquote><p>语义缓存（相似问题复用）、精确缓存、热点预生成、模型路由小模型处理简单问题。</p></blockquote><p><strong>20. RAG 多租户怎么隔离？</strong></p><blockquote><p>向量库按 tenant 过滤/独立 collection、行级权限、对话归属校验防泄漏。</p></blockquote><p><strong>21. 设计一个 LLM 对话 API（含流式）？</strong></p><blockquote><p>网关（鉴权/限流/成本）→ 模型路由 → 消费上游 SSE → 转发前端；加缓存/降级/追踪。</p></blockquote><h2 id="七、测试-运维" tabindex="-1">七、测试 / 运维 <a class="header-anchor" href="#七、测试-运维" aria-label="Permalink to &quot;七、测试 / 运维&quot;">​</a></h2><p><strong>22. AI 输出不确定怎么写测试？</strong></p><blockquote><p>不测逐字相等，测属性：评测集+自动打分（LLM-as-Judge）；关键逻辑确定性 mock。</p></blockquote><p><strong>23. 推理服务怎么扩缩容？</strong></p><blockquote><p>按并发/GPU 利用率扩 Pod；连续批处理提吞吐；监控 KV Cache 与并发。</p></blockquote><p><strong>24. AI 运维多了什么？</strong></p><blockquote><p>模型层指标：token 用量、延迟分解、幻觉率、评测分、Prompt 版本、成本告警。</p></blockquote><p><strong>25. Prompt 改坏效果怎么防？</strong></p><blockquote><p>维护评测集、CI 跑评测门禁、版本管理可回滚、灰度。</p></blockquote><h2 id="八、ai-应用-商业化" tabindex="-1">八、AI 应用 / 商业化 <a class="header-anchor" href="#八、ai-应用-商业化" aria-label="Permalink to &quot;八、AI 应用 / 商业化&quot;">​</a></h2><p><strong>26. 为什么很多 AI 项目失败？</strong></p><blockquote><p>无真痛点、成本算不过账、可靠性不达标、数据/合规卡死、护城河低（套壳）。</p></blockquote><p><strong>27. 套壳 API 产品风险？</strong></p><blockquote><p>无护城河、毛利受 API 成本挤压、易被替代；需走数据/工作流/领域深度。</p></blockquote><p><strong>28. 高价值 AI 落地场景？</strong></p><blockquote><p>客服问答、代码助手、文档处理、营销内容、数据分析、垂直行业（法律/医疗/金融）。</p></blockquote><p><strong>29. AI 应用架构最易漏的环节？</strong></p><blockquote><p>可观测与评测闭环、降级与成本治理、安全与权限。</p></blockquote><p><strong>30. 私有化 vs 云 API 怎么选？</strong></p><blockquote><p>数据敏感/合规/规模大 → 私有化；快速验证 → 云 API 起步后迁移。</p></blockquote><hr><p>➡️ 返回：<a href="./../面试真题集/README">面试真题集 README</a></p>',73)])])}const g=t(r,[["render",n]]);export{q as __pageData,g as default};
